public static boolean shouldShowGUPUI(FormRun _formRun, ModuleInventCustVend _custVendValue, boolean _useDirectValue)
{
    boolean showGUPUI = next shouldShowGUPUI(_formRun, _custVendValue, _useDirectValue);

    if (_useDirectValue)
    {
        showGUPUI = GUPGlobalEnableFeatureHelper::useAttributeBasedPricing()
                    && (_custVendValue == ModuleInventCustVend::Cust
                    || _custVendValue == ModuleInventCustVend::Vend);
    }
    else
    {
        FormDataSource TAMRebateDeal_ds = _formRun.dataSource(tablestr(TAMRebateDeal));
        TAMRebateDeal  rebateDeal = TAMRebateDeal_ds.cursor();
        showGUPUI = GUPRebateMatchingHelper::isGUPCustomerRebate(rebateDeal);
    }

    return showGUPUI;
}
